module min_distance (\n    input [3:0] n,\n    input signed [7:0] a0, a1, a2, a3, a4, a5, a6, a7,\n    output reg [31:0] result\n);\n\n    // Prefix sums\n    wire signed [15:0] p [0:8];\n    assign p[0] = 16'sd0;\n    assign p[1] = a0;\n    assign p[2] = p[1] + a1;\n    assign p[3] = p[2] + a2;\n    assign p[4] = p[3] + a3;\n    assign p[5] = p[4] + a4;\n    assign p[6] = p[5] + a5;\n    assign p[7] = p[6] + a6;\n    assign p[8] = p[7] + a7;\n\n    // Distance computation wires\n    wire [31:0] dist [1:8][1:8];\n\n    genvar i, j;\n    generate\n        for (i=1; i <=8; i=i+1) begin : gen_i\n            for (j=1; j <=8; j=j+1) begin : gen_j\n                if (j > i) begin\n                    wire signed [3:0] dx = i - j;\n                    wire signed [15:0] dy = p[i] - p[j];\n                    wire [31:0] dx_sq = (dx) * (dx);\n                    wire [31:0] dy_sq = (dy) * (dy);\n                    assign dist[i][j] = dx_sq + dy_sq;\n                end else begin\n                    assign dist[i][j] = 32'hFFFF_FFFF;\n                end\n            end\n        end\n    endgenerate\n\n    // Find minimum distance\n    integer k, l;\n    always @(*) begin\n        result = 32'hFFFF_FFFF;\n        for (k=1; k<=8; k=k+1) begin\n            for (l=1; l<=8; l=l+1) begin\n                if (j > i) begin\n                    if (k <= n && l <= n && dist[k][l] < result) begin\n                        result = dist[k][l];\n                    end\n                end\n            end\n        end\n    end\n\nendmodule